3	/// How a request treats end-of-sequence tokens.
4	#[derive(Clone, Copy, Debug, Default, Eq, PartialEq)]
5	pub enum EosPolicy {
6	    /// Do not stop on model EOS tokens.
7	    Ignore,
8	    /// Use the model executor's configured EOS set.
9	    #[default]
10	    ModelDefault,
11	    /// Use this protocol-provided primary EOS ID; secondary EOS IDs arrive
12	    /// in the request's explicit stop-token set.
13	    Token(u32),
14	}
15	
16	/// Request-scoped token stopping policy.
17	///
18	/// The vLLM primary EOS has no `stop_reason`; other matches, including
19	/// secondary EOS IDs lowered into the explicit stop set, report the token ID.
20	#[derive(Clone, Debug, Default, Eq, PartialEq)]
21	pub struct StopPolicy {
22	    eos: EosPolicy,
23	    /// Sorted and deduplicated explicit stop IDs.
24	    ///
25	    /// Requests clone this policy while building a plan and sending it to
26	    /// worker ranks. Keeping the normalized set behind an `Arc` makes those
27	    /// clones cheap and lets classification use binary search for large stop
28	    /// sets without regressing the common one-ID case.
29	    token_ids: Arc<[u32]>,
30	}
31	
32	impl StopPolicy {
33	    /// Build a policy from wire-provided stop IDs.
34	    ///
35	    /// Normalization happens once at the request boundary. Internal copies can
36	    /// then share the immutable slice instead of repeatedly sorting, deduping,
37	    /// or cloning the caller's vector.
38	    #[must_use]
39	    pub fn new(eos: EosPolicy, mut token_ids: Vec<u32>) -> Self {
40	        token_ids.sort_unstable();
41	        token_ids.dedup();
42	        Self {
43	            eos,
44	            token_ids: token_ids.into(),
45	        }
46	    }
47	
48	    /// Classify a token using vLLM's priority: EOS first, then the request's
49	    /// explicit stop-token set.
50	    #[must_use]
51	    pub fn classify(
52	        &self,
53	        token_id: u32,
54	        is_model_eos: impl FnOnce(u32) -> bool,
55	    ) -> Option<StopCause> {
56	        let is_primary_eos = match self.eos {
57	            EosPolicy::Ignore => false,
58	            EosPolicy::ModelDefault => is_model_eos(token_id),
59	            EosPolicy::Token(eos_token_id) => token_id == eos_token_id,
60	        };
61	
62	        if is_primary_eos {
63	            Some(StopCause::Eos(token_id))
64	        } else if self.token_ids.binary_search(&token_id).is_ok() {
65	            Some(StopCause::Token(token_id))
66	        } else {
67	            None
68	        }
69	    }
70	}
