116	impl Scheduler for EchoScheduler {
117	    fn submit(&mut self, request: QueuedRequest) {
118	        self.queued.push(request);
119	    }
120	
121	    fn step(&mut self, ledger: &mut RequestLedger) -> Result<()> {
122	        for QueuedRequest { id, request } in self.queued.drain(..) {
123	            if ledger.is_aborted(id) {
124	                ledger.retire(id);
125	                continue;
126	            }
127	            let echo_len = request.prompt_tokens.len().min(request.max_tokens);
128	            let truncated = echo_len < request.prompt_tokens.len();
129	            let mut pending = Vec::from(&request.prompt_tokens[..echo_len]);
130	            pending.reverse();
131	            ledger.admit(id);
132	            self.running.push(RunningRequest {
133	                id,
134	                pending,
135	                truncated,
136	            });
137	        }
138	        let mut still_running = Vec::new();
139	        for mut running in self.running.drain(..) {
140	            if ledger.is_aborted(running.id) {
141	                ledger.retire(running.id);
142	                continue;
143	            }
144	            if let Some(token) = running.pending.pop() {
145	                ledger.push_tokens(running.id, &[token], &[]);
146	                still_running.push(running);
147	            } else {
148	                let reason = if running.truncated {
149	                    FinishReason::Length
150	                } else {
151	                    FinishReason::Stop
152	                };
153	                ledger.finish(running.id, reason);
154	            }
155	        }
156	        self.running = still_running;
157	        Ok(())
158	    }
